CREATE TABLE org_unit(org_id TEXT NOT NULL REFERENCES organization(id),id TEXT NOT NULL,code TEXT NOT NULL CHECK(length(code) BETWEEN 1 AND 64),kind TEXT NOT NULL CHECK(kind IN('business_group','division','department')),PRIMARY KEY(org_id,id),UNIQUE(org_id,kind,code),UNIQUE(org_id,id,kind)) STRICT;
