CREATE TABLE org_unit_parent_history(org_id TEXT NOT NULL,id TEXT NOT NULL,child_unit_id TEXT NOT NULL,parent_unit_id TEXT NOT NULL,valid_from TEXT NOT NULL CHECK(length(valid_from)=10 AND date(valid_from,'+0 days')=valid_from),valid_to TEXT CHECK(valid_to IS NULL OR (length(valid_to)=10 AND date(valid_to,'+0 days')=valid_to AND valid_from<valid_to)),change_id TEXT,PRIMARY KEY(org_id,id),FOREIGN KEY(org_id,child_unit_id) REFERENCES org_unit(org_id,id),FOREIGN KEY(org_id,parent_unit_id) REFERENCES org_unit(org_id,id),FOREIGN KEY(org_id,change_id) REFERENCES structure_change(org_id,id),CHECK(child_unit_id<>parent_unit_id)) STRICT;
CREATE TABLE education_level(code TEXT PRIMARY KEY CHECK(code IN('Master','Bachelor','Diploma')),rank INTEGER NOT NULL UNIQUE CHECK(rank BETWEEN 1 AND 3),CHECK((code='Master' AND rank=3) OR (code='Bachelor' AND rank=2) OR (code='Diploma' AND rank=1))) STRICT;
