CREATE TABLE structure_change_item(org_id TEXT NOT NULL,change_id TEXT NOT NULL,ordinal INTEGER NOT NULL CHECK(ordinal BETWEEN 0 AND 99),action TEXT NOT NULL CHECK(action IN('create','add','end','replace')),kind TEXT NOT NULL CHECK(kind IN('legal_entity','business_group','division','department','org_unit_parent','job_family','career_level','identifier','employment','education','job_assignment','reporting','employee_lifecycle')),fact_id TEXT,employee_id TEXT,owner_id TEXT,valid_from TEXT CHECK(valid_from IS NULL OR (length(valid_from)=10 AND date(valid_from,'+0 days')=valid_from)),valid_to TEXT CHECK(valid_to IS NULL OR (length(valid_to)=10 AND date(valid_to,'+0 days')=valid_to)),effective_to TEXT CHECK(effective_to IS NULL OR (length(effective_to)=10 AND date(effective_to,'+0 days')=effective_to)),supersedes_id TEXT,CHECK(valid_to IS NULL OR valid_from<valid_to),PRIMARY KEY(org_id,change_id,ordinal),FOREIGN KEY(org_id,change_id) REFERENCES structure_change(org_id,id),FOREIGN KEY(org_id,employee_id) REFERENCES employee(org_id,id)) STRICT;
CREATE TABLE workforce_command_receipt(org_id TEXT NOT NULL,subject_id TEXT NOT NULL,operation TEXT NOT NULL CHECK(operation IN('OP-ORG-09','OP-ORG-10')),key TEXT NOT NULL,digest BLOB NOT NULL CHECK(length(digest)=32),digest_key_version INTEGER NOT NULL CHECK(digest_key_version>0),result_change_id TEXT NOT NULL,graph_revision INTEGER NOT NULL CHECK(graph_revision>0),catalog_revision INTEGER NOT NULL CHECK(catalog_revision>0),result_json TEXT NOT NULL CHECK(json_valid(result_json) AND json_type(result_json)='object'),PRIMARY KEY(org_id,subject_id,operation,key),FOREIGN KEY(org_id,subject_id) REFERENCES subject(org_id,id),FOREIGN KEY(org_id,result_change_id) REFERENCES structure_change(org_id,id)) STRICT;
